// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.36;
contract Base {
    struct Pair { uint256 value; address owner; }
    event Seen(address indexed who, Pair pair);
    error Bad(uint256 code);
    function ping(Pair calldata pair, uint256[] calldata values) external pure returns (bytes32 result) {}
}
contract C is Base {
    uint256 public count;
    mapping(address => uint256) public balances;
    constructor(uint256 initial) payable {}
    fallback() external payable {}
    receive() external payable {}
}
